    const session = await sessionResponse.json();
    csrf = session.csrf;
    hasRecoverableCode = !!session.hasRecoverableCode;
    const fromLink = new URLSearchParams(location.search).get("reset");
    if (currentStep === 2 && !hasRecoverableCode && !fromLink) {
