      const result = await call("/api/reset/verify", { token: fromLink });
      status("verifyStatus", result.message, !result.ok);
      if (result.ok) showStep(3);
      history.replaceState({}, "", "/recovery");
    } else if (currentStep === 2 && hasRecoverableCode) {
