const LOCK_MS = 15 * 60 * 1000;
const WINDOW_MS = 10 * 60 * 1000;
const ISSUANCE_WINDOW_MS = 10 * 60 * 1000;
const ISSUANCE_LOCK_MS = 15 * 60 * 1000;
