const SIMULATION_MODE = true;

type Account = {
  id: string;
  recoveryChannel: string;
  passwordHash: string;
  privacyAccepted: boolean;
};
type Attempt = { count: number; started: number; lockedUntil: number };
type ResetRecord = { token: string; accountId: string; expiresAt: number; used: boolean };
type Session = {
  id: string;
  csrf: string;
  reset?: ResetRecord;
  verifiedReset?: string;
  mfaSent?: boolean;
  mfaVerified?: boolean;
  authenticatedAccountId?: string;
  attempts: Record<string, Attempt>;
};

/* Requirement 4: pre-generated bcrypt hash only; no initial plaintext password is retained. */
const demoAccount: Account = {
  id: "acct_7cba6f1d_server_only",
